export default function Section() {
  return (
    <Category>
      {c => (
        <section className="bg-secondary-900 text-white" aria-label={c.name}>
          <div className="grid">
            {c.image && (
              <div className="col-start-1 row-start-1 md:hidden">
                <Image
                  src={c.mobileImage || c.image}
                  alt={c.name}
                  aspect="4:5"
                  fit="cover"
                  sizes="100vw"
                  priority={true}
                />
              </div>
            )}
            {c.image && (
              <div className="col-start-1 row-start-1 hidden md:block">
                <Image
                  src={c.image}
                  alt={c.name}
                  aspect="21:9"
                  fit="cover"
                  sizes="100vw"
                  priority={true}
                />
              </div>
            )}
            {c.image && (
              <div
                className="col-start-1 row-start-1 bg-gradient-to-t from-secondary-900 via-secondary-900/50 to-secondary-900/30"
                aria-hidden="true"
              />
            )}
            <div
              className="col-start-1 row-start-1 m-3 sm:m-5 md:m-8 border border-primary-300/30 pointer-events-none"
              aria-hidden="true"
            />
            <div
              className={`col-start-1 row-start-1 relative flex flex-col items-center justify-between gap-10 px-6 pt-10 pb-12 sm:px-10 md:pt-14 md:pb-20 text-center ${c.image ? '' : 'min-h-96 md:min-h-[32rem]'}`}
            >
              <nav aria-label="Breadcrumb" className="w-full">
                <Breadcrumbs>
                  {b => (
                    <span className="inline-flex items-center text-xs uppercase tracking-widest">
                      {b.current ? (
                        <span aria-current="page" className="py-3 text-primary-300">
                          {b.name}
                        </span>
                      ) : (
                        <Link
                          href={b.url || '/'}
                          className="inline-flex min-h-11 items-center text-white/70 hover:text-primary-300 transition-colors duration-500"
                        >
                          {b.name}
                        </Link>
                      )}
                      {!b.current && (
                        <span className="mx-3 text-primary-300/60" aria-hidden="true">
                          /
                        </span>
                      )}
                    </span>
                  )}
                </Breadcrumbs>
              </nav>

              <Reveal effect="fade" delay={0.2}>
                <div className="flex max-w-3xl flex-col items-center">
                  <div className="flex items-center gap-4 text-primary-300" aria-hidden="true">
                    <span className="h-px w-10 sm:w-16 bg-primary-300/50" />
                    <Icon name="diamond" size="xs" strokeWidth={1} />
                    <span className="h-px w-10 sm:w-16 bg-primary-300/50" />
                  </div>
                  <h1 className="mt-6 font-display text-3xl font-light uppercase leading-tight tracking-widest text-white sm:text-5xl lg:text-7xl">
                    {c.name}
                  </h1>
                  {c.tagline && (
                    <p className="mt-5 font-display text-lg italic text-accent-300 sm:text-2xl">
                      {c.tagline}
                    </p>
                  )}
                  {c.productCount > 0 && (
                    <p className="mt-8 text-xs uppercase tracking-widest text-white/70">
                      {c.productCount} products
                    </p>
                  )}
                </div>
              </Reveal>
            </div>
          </div>

          <Reveal effect="fade-up" delay={0.4}>
            <SubCategories
              layout="list"
              className="mx-auto flex max-w-5xl flex-wrap justify-center gap-3 px-5 py-10 md:py-14"
            >
              {s => (
                <Link
                  href={s.url}
                  className="inline-flex min-h-11 items-center rounded-none border border-primary-300/40 px-5 text-sm uppercase tracking-widest text-white/80 transition-colors duration-500 hover:border-primary-300 hover:text-primary-300"
                >
                  {s.name}
                </Link>
              )}
            </SubCategories>
          </Reveal>
        </section>
      )}
    </Category>
  )
}

export default function Section() {
  return (
    <section className="relative bg-secondary-900 text-white overflow-hidden">
      <div className="absolute inset-x-0 top-0 h-px bg-primary-300/40" aria-hidden="true" />
      <div className="mx-auto max-w-6xl px-5 sm:px-8 pt-8 md:pt-10 pb-16 md:pb-28">
        <nav aria-label="Breadcrumb" className="flex justify-center md:justify-start">
          <div className="flex flex-wrap items-center justify-center md:justify-start gap-x-3 gap-y-1 text-xs uppercase tracking-widest text-white/60">
            <Breadcrumbs>
              {c =>
                c.url && !c.current ? (
                  <span className="inline-flex items-center gap-3">
                    <Link
                      href={c.url}
                      className="inline-flex min-h-11 items-center hover:text-primary-300 transition-colors duration-500"
                    >
                      {c.name}
                    </Link>
                    <span className="text-primary-300/60" aria-hidden="true">/</span>
                  </span>
                ) : (
                  <span aria-current="page" className="inline-flex min-h-11 items-center text-primary-300">
                    {c.name}
                  </span>
                )
              }
            </Breadcrumbs>
          </div>
        </nav>

        <Brand>
          {b => (
            <div className="mt-10 md:mt-16 grid grid-cols-1 md:grid-cols-12 gap-12 md:gap-16 lg:gap-24 items-center">
              <figure className="md:col-span-5 w-full max-w-sm mx-auto md:max-w-none">
                <div className="relative border border-primary-300/40 p-3 sm:p-4">
                  <span className="absolute -top-px -left-px h-6 w-6 border-t border-l border-primary-300" aria-hidden="true" />
                  <span className="absolute -bottom-px -right-px h-6 w-6 border-b border-r border-primary-300" aria-hidden="true" />
                  {b.image ? (
                    <div className="relative">
                      <Image
                        src={b.image}
                        alt={b.name}
                        aspect="4:5"
                        fit="cover"
                        priority={true}
                        sizes="(min-width: 768px) 40vw, 90vw"
                        className="rounded-none"
                      />
                      <div className="absolute inset-0 bg-secondary-900/30" aria-hidden="true" />
                      <div className="absolute inset-x-5 bottom-5 sm:inset-x-8 sm:bottom-8 bg-surface px-6 py-6 sm:px-8 flex items-center justify-center">
                        {b.logo ? (
                          <div className="w-full max-w-48">
                            <Image src={b.logo} alt={`${b.name} logo`} aspect="3:2" fit="contain" />
                          </div>
                        ) : (
                          <span className="font-display uppercase tracking-widest text-xl text-secondary-900 text-center">
                            {b.name}
                          </span>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className="bg-surface aspect-square flex flex-col items-center justify-center gap-6 px-8">
                      {b.logo ? (
                        <div className="w-full max-w-56">
                          <Image src={b.logo} alt={`${b.name} logo`} aspect="3:2" fit="contain" priority={true} />
                        </div>
                      ) : (
                        <>
                          <Icon name="diamond" size="lg" strokeWidth={1} className="text-primary-700" />
                          <span className="font-display uppercase tracking-widest text-2xl text-secondary-900 text-center">
                            {b.name}
                          </span>
                        </>
                      )}
                    </div>
                  )}
                </div>
                {b.productCount > 0 && (
                  <figcaption className="mt-5 flex items-center justify-center gap-4 text-xs uppercase tracking-widest text-white/60">
                    <span className="h-px w-8 bg-primary-300/40" aria-hidden="true" />
                    <span>
                      <span className="text-primary-300">{b.productCount}</span> pieces in the collection
                    </span>
                    <span className="h-px w-8 bg-primary-300/40" aria-hidden="true" />
                  </figcaption>
                )}
              </figure>

              <div className="md:col-span-7 text-center md:text-left">
                <p className="text-xs uppercase tracking-widest text-primary-300">The house of</p>
                <h1 className="mt-5 font-display font-light uppercase tracking-widest text-4xl sm:text-5xl lg:text-7xl leading-tight text-white break-words">
                  {b.name}
                </h1>
                <div className="mt-8 flex items-center justify-center md:justify-start gap-3" aria-hidden="true">
                  <span className="h-px w-12 bg-primary-300/60" />
                  <span className="h-1.5 w-1.5 rotate-45 border border-primary-300" />
                  <span className="h-px w-12 bg-primary-300/60" />
                </div>

                {b.tagline && (
                  <p className="mt-8 font-display italic text-xl sm:text-2xl lg:text-3xl text-accent-300 leading-snug">
                    {b.tagline}
                  </p>
                )}
                {b.description && (
                  <p className="mt-6 text-base md:text-lg leading-relaxed text-white/70 max-w-xl mx-auto md:mx-0">
                    {b.description}
                  </p>
                )}

                {(b.founded || b.origin || b.headquarters) && (
                  <dl className="mt-10 grid grid-cols-1 sm:grid-cols-3 gap-6 border-y border-primary-300/30 py-6 max-w-xl mx-auto md:mx-0">
                    {b.founded && (
                      <div>
                        <dt className="text-xs uppercase tracking-widest text-primary-300">Since</dt>
                        <dd className="mt-2 font-display text-xl text-white">{b.founded}</dd>
                      </div>
                    )}
                    {b.origin && (
                      <div>
                        <dt className="text-xs uppercase tracking-widest text-primary-300">Origin</dt>
                        <dd className="mt-2 font-display text-xl text-white">{b.origin}</dd>
                      </div>
                    )}
                    {b.headquarters && (
                      <div>
                        <dt className="text-xs uppercase tracking-widest text-primary-300">Based in</dt>
                        <dd className="mt-2 font-display text-xl text-white">{b.headquarters}</dd>
                      </div>
                    )}
                  </dl>
                )}

                <div className="mt-10 flex flex-col sm:flex-row flex-wrap items-center md:items-start justify-center md:justify-start gap-6 sm:gap-8">
                  {b.website && (
                    <Link
                      href={b.website}
                      target="_blank"
                      className="inline-flex min-h-12 items-center gap-3 rounded-none border border-primary-300 px-7 text-xs uppercase tracking-widest text-primary-300 transition-colors duration-500 hover:bg-primary-300 hover:text-secondary-900"
                    >
                      Visit the website
                      <Icon name="arrow-up-right" size="sm" strokeWidth={1.25} />
                    </Link>
                  )}
                  {b.socials.length > 0 && (
                    <ul className="flex flex-wrap items-center justify-center md:justify-start gap-x-6 gap-y-1" aria-label="Follow the brand">
                      {b.socials.map(s => (
                        <li key={s.href}>
                          <Link
                            href={s.href}
                            target="_blank"
                            className="inline-flex min-h-11 items-center border-b border-transparent text-sm uppercase tracking-widest text-white/70 transition-colors duration-500 hover:text-primary-300 hover:border-primary-300/60"
                          >
                            {s.label}
                          </Link>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            </div>
          )}
        </Brand>
      </div>
      <div className="absolute inset-x-0 bottom-0 h-px bg-primary-300/40" aria-hidden="true" />
    </section>
  )
}

export default function Section() {
  return (
    <section className="mx-auto w-full max-w-6xl px-4 py-8 md:py-12">
      <div className="flex flex-col gap-6">
        <ProductGallery />
        <ProductTitle />
        <ProductPrice />
        <VariantPicker />
        <AddToCart />
      </div>
    </section>
  )
}
